369	    /// Walk the clobber chain from a Use to find the nearest Def that
370	    /// must-alias or may-alias the use's location.
371	    ///
372	    /// Returns the MemoryAccessId of the clobbering Def, or None if we
373	    /// reach the function entry without finding one.
374	    pub fn get_clobbering_access(&self, use_id: MemoryAccessId) -> Option<MemoryAccessId> {
375	        let use_loc = match self.accesses.get(&use_id)? {
376	            MemoryAccess::Use {
377	                location,
378	                defining_access,
379	                ..
380	            } => (location.clone(), *defining_access),
381	            _ => return None,
382	        };
383	        let (loc, mut current) = use_loc;
384	        let mut visited = 0u32;
385	        const MAX_WALK: u32 = 100;
386	
387	        while let Some(cur_id) = current {
388	            if visited >= MAX_WALK {
389	                return Some(cur_id); // conservative: assume it clobbers
390	            }
391	            visited += 1;
392	
393	            match self.accesses.get(&cur_id)? {
394	                MemoryAccess::Def {
395	                    id,
396	                    location: def_loc,
397	                    reaching_def,
398	                    is_volatile,
399	                } => {
400	                    // Volatile/atomic: always a clobber (opaque barrier).
401	                    if *is_volatile {
402	                        return Some(*id);
403	                    }
404	                    // Must-alias: this is THE defining store.
405	                    if def_loc.must_alias(&loc) {
406	                        return Some(*id);
407	                    }
408	                    // Must-not-alias: skip this def, continue walking.
409	                    if def_loc.must_not_alias(&loc) {
410	                        current = *reaching_def;
411	                        continue;
412	                    }
413	                    // May-alias: conservative, treat as clobber.
414	                    return Some(*id);
415	                }
416	                MemoryAccess::Phi { .. } => {
417	                    // Conservative: if any phi input could clobber, return this phi.
418	                    // A real implementation would walk each arm.
419	                    return Some(cur_id);
420	                }
421	                MemoryAccess::Use { .. } => {
422	                    // Uses don't clobber; shouldn't appear in the chain.
423	                    return None;
424	                }
425	            }
426	        }
427	
428	        None
429	    }
