431	    /// Check if a Def is "dead" — no Use reaches it before the next Def
432	    /// to the same location.
433	    pub fn is_dead_store(&self, def_id: MemoryAccessId) -> bool {
434	        if !matches!(self.accesses.get(&def_id), Some(MemoryAccess::Def { .. })) {
435	            return false;
436	        }
437	
438	        // Find any Use that has this def as its defining access.
439	        let has_live_use = self.accesses.values().any(|access| {
440	            matches!(access, MemoryAccess::Use { defining_access: Some(da), .. } if *da == def_id)
441	        });
442	
443	        !has_live_use
444	    }
